const requiredHeaders=['id','name','role','department','tenure_years','job_description','career_path','next_role','type','skill','initial','current','weight','development_action'];
const optionalHeaders=['initial_date','current_date','assessor','evidence','target','aspiration','development_owner','development_due','history','availability'];
const headers=[...requiredHeaders,...optionalHeaders];
const advice={Leadership:'Affiancare un team leader e coordinare una breve riunione di reparto.',Comunicazione:'Allenare passaggi di consegna chiari e chiedere feedback ai colleghi.','Lavoro di squadra':'Partecipare a un’attività interfunzionale e condividere obiettivi e risultati.','Problem solving':'Analizzare un problema ricorrente con il metodo dei 5 perché.','Capacità decisionale':'Discutere casi pratici con il responsabile e motivare le scelte.',Responsabilità:'Concordare un obiettivo misurabile e verificarne periodicamente i risultati.','Attenzione alla sicurezza':'Ripassare le procedure e partecipare a un confronto sui rischi di reparto.','Orientamento alla qualità':'Rivedere una non conformità e proporre un’azione correttiva.',Adattabilità:'Svolgere un affiancamento su una diversa postazione.','Gestione dei conflitti':'Esercitare ascolto attivo e confronto costruttivo con un tutor.'};
function sampleRows(){return people.flatMap(p=>{const role=roleProfiles[p[10]];const extras=(current,initial,target)=>['2023-01-15','2026-01-15','Responsabile di reparto','Esempio simulato: osservazione da verificare.',target,'Disponibile a esplorare un percorso di coordinamento.','Responsabile e collaboratore','2026-12-15',`2023-01-15:${initial}|2024-07-15:${clampScore((initial+current)/2)}|2026-01-15:${current}`,'Disponibilità da discutere durante il colloquio.'];return [...softNames.map((skill,i)=>{const initial=clampScore(p[8][i]-(0.3+(i%4)*0.15));return [...p.slice(0,8),'soft',skill,initial,p[8][i],i===0?1.5:1,advice[skill],...extras(p[8][i],initial,[4,4,4,4,3.5,4,4.5,4,3.5,4][i])] }),...role.hard.map((skill,i)=>{const initial=clampScore(p[9][i]-(0.3+(i%3)*0.15));return [...p.slice(0,8),'hard',skill,initial,p[9][i],role.weights[i],'Concordare con il responsabile formazione pratica e verifica sul campo.',...extras(p[9][i],initial,i===3?4.5:4)]})]});}

function csvEncode(rows){return '\ufeff'+[headers,...rows].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');}
function parseCSV(text){text=text.replace(/^\ufeff/,'');const first=text.split(/\r?\n/,1)[0];const sep=first.includes(';')?';':',';let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"'){if(field)throw Error('Invalid quotes in the CSV file.');quoted=true;}else if(c===sep){row.push(field);field='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);field='';if(row.some(v=>v.trim()))rows.push(row);row=[];}else field+=c;}if(quoted)throw Error('Unclosed quotes in the CSV file.');row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value;}
function parseHistory(value,row){const points=value.split('|').map(entry=>{const [date,raw,...extra]=entry.trim().split(':');const score=Number((raw||'').replace(',','.'));if(extra.length||!validDate(date)||!raw||!Number.isFinite(score)||score<1||score>5)throw Error('Row '+row+': history must contain YYYY-MM-DD:score entries between 1 and 5.');return {date,score}});if(points.some((p,i)=>i>0&&p.date<=points[i-1].date))throw Error('Row '+row+': history dates must be unique and chronological.');return points;}
function loadData(rows){if(rows.length<2)throw Error('The file is empty.');const aliases={nome:'name',ruolo:'role',reparto:'department',anzianita_anni:'tenure_years',percorso:'career_path',prossimo_ruolo:'next_role',tipo:'type',iniziale:'initial',attuale:'current',peso:'weight',azione_sviluppo:'development_action'};const head=rows[0].map(x=>{const key=x.trim().toLowerCase();return aliases[key]||key});for(const h of requiredHeaders)if(!head.includes(h))throw Error('Missing required column: '+h);const idx=Object.fromEntries(headers.map(h=>[h,head.indexOf(h)]));const byId=new Map();for(let n=1;n<rows.length;n++){const obj=Object.fromEntries(headers.map(h=>[h,String(rows[n][idx[h]]??'').trim()]));if(!obj.id||!obj.name||!obj.department||!obj.skill||!['soft','hard'].includes(obj.type.toLowerCase()))throw Error('Row '+(n+1)+': check ID, name, department, type (soft/hard), and skill.');obj.type=obj.type.toLowerCase();for(const key of ['initial','current','weight']){const raw=obj[key].replace(',','.');if(!raw||!Number.isFinite(Number(raw)))throw Error('Row '+(n+1)+': '+key+' must be a number.');obj[key]=Number(raw);}if(obj.initial<1||obj.initial>5||obj.current<1||obj.current>5||obj.weight<=0)throw Error('Row '+(n+1)+': scores must be between 1 and 5 and weight must be positive.');if(obj.target){const target=Number(obj.target.replace(',','.'));if(!Number.isFinite(target)||target<1||target>5)throw Error('Row '+(n+1)+': target must be between 1 and 5.');obj.target=target}for(const field of ['initial_date','current_date','development_due'])if(obj[field]&&!validDate(obj[field]))throw Error('Row '+(n+1)+': '+field+' must use a valid YYYY-MM-DD date.');if(obj.history)parseHistory(obj.history,n+1);if(!byId.has(obj.id))byId.set(obj.id,{...obj,skills:[]});const p=byId.get(obj.id);for(const key of ['name','role','department','tenure_years','job_description','career_path','next_role','aspiration','availability'])if(p[key]!==obj[key])throw Error('Row '+(n+1)+': inconsistent personal data for '+obj.id+'.');if(p.skills.some(s=>s.type===obj.type&&s.skill===obj.skill))throw Error('Row '+(n+1)+': duplicate skill for '+obj.name+'.');p.skills.push(obj);}const result=[...byId.values()];for(const p of result)if(!p.skills.some(s=>s.type==='soft')||!p.skills.some(s=>s.type==='hard'))throw Error(p.name+': at least one soft skill and one hard skill are required.');return result;}
function average(skills){return skills.reduce((a,s)=>a+s.current*s.weight,0)/skills.reduce((a,s)=>a+s.weight,0)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function radar(skills,animate){const n=skills.length,c=150,r=93,pt=(i,v)=>{const a=2*Math.PI*i/n-Math.PI/2;return [c+Math.cos(a)*r*v/5,c+Math.sin(a)*r*v/5]};const points=(v)=>skills.map((s,i)=>pt(i,typeof v==='string'?s[v]:v).join(',')).join(' ');let svg=`<svg viewBox="0 0 300 300" role="img" aria-label="${language==='en'?'Radar chart of initial and current soft skills':'Grafico radar delle soft skill iniziali e attuali'}">`;for(let k=1;k<=5;k++)svg+=`<polygon points="${points(k)}" fill="none" stroke="var(--chart-grid)" stroke-width=".7"/>`;skills.forEach((s,i)=>{const [x,y]=pt(i,5),[lx,ly]=pt(i,5.75);svg+=`<line x1="${c}" y1="${c}" x2="${x}" y2="${y}" stroke="var(--chart-grid)" stroke-width=".7"/><text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" fill="var(--chart-label)" font-size="7">${i+1}</text>`});for(const [key,color] of [['initial','var(--chart-initial)'],['current','var(--chart-current)']]){svg+=`<g class="radar-series radar-series--${key}${animate?' radar-series--animate':''}"><polygon points="${points(key)}" fill="${color}" fill-opacity=".22" stroke="${color}" stroke-width="2"/>`;skills.forEach((s,i)=>{const [x,y]=pt(i,s[key]);svg+=`<circle cx="${x}" cy="${y}" r="2.6" fill="${color}"/>`});svg+='</g>'}return svg+'</svg>';}
