let dataset=loadData([headers,...sampleRows()]);let current=dataset[0].id,selectedDepartment='',searchTerm='',datasetRevision=0,lastAnimatedProfile='',mainView='people',profileTab='overview',teamDepartment='',teamRole='';const $=id=>document.getElementById(id);
